export const PUT = auth(async (req, res) => {
  const body = await req.json();
  if (body.name.length < 3) {
    return Response.json({
      status: 400,
      body: {
        error: "Name must be at least 3 characters",
      },
    });
  }

  const user = await prisma.user.findFirst({
    where: {
      ownedSquads: {
        some: {
          ownerId: req?.auth?.user?.id,
        },
      },
    },
    select: {
      ownedSquads: {
        select: {
          id: true,
        },
      },
    },
  });

  if (!user) {
    return Response.json({
      status: 200,
      body: {
        message: "You don't own a squad",
      },
    });
  }

  await prisma.squad.update({
    where: {
      id: user.ownedSquads[0].id,
    },
    data: {
      name: body.name,
      allowOthersToJoin: body.allowRandomJoin,
    },
  });

  return Response.json({
    status: 200,
    body: {
      message: "Success",
    },
  });
});

import { auth } from '@frontend/auth';
import Airtable from 'airtable';
import moment from 'moment';
import { object, string, array } from 'yup';
import { prisma } from '@db/prisma';
import { loadUserUnclaimedPrizes } from '@db/queries/load.member.prizes';
const validation = object({
  type: array().required(),
  first_name: string().required(),
  last_name: string().required(),
  email: string().required().email(),
  phone_number: string()
    .required()
    .matches(
      /\+(9[976]\d|8[987530]\d|6[987]\d|5[90]\d|42\d|3[875]\d|2[98654321]\d|9[8543210]|8[6421]|6[6543210]|5[87654321]|4[987654310]|3[9643210]|2[70]|7|1)\d{1,14}$/,
      'Is not in correct format'
    ),
  shipping_address1: string().required(),
  shipping_city: string().required(),
  shipping_state: string().required(),
  shipping_zip: string().required(),
  shipping_country: string().required(),
  shirt_size: string()
    .required()
    .oneOf(['Small', 'Medium', 'Large', 'X-Large', '2X-Large']),
});

const airTable = new Airtable({ apiKey: [REDACTED] });

export const POST = auth(async (req, context) => {
  const body = await req.json();
  if (!req?.auth?.user?.id! || !validation.validateSync(body)) {
    return Response.json({ invalid: true });
  }

  const winners = await loadUserUnclaimedPrizes(req?.auth?.user?.id!);

  if (winners.length === 0) {
    return Response.json({ invalid: true });
  }

  const selectedWins = body.type.filter(
    (p: any) => winners.map((w) => w.id).indexOf(p) > -1
  );

  if (!selectedWins.length || body.type.length !== selectedWins.length) {
    return Response.json({ invalid: true });
  }

  const winnersMap = selectedWins.map((s: any) => winners.find((w) => w.id === s));

  await Promise.all(
    winnersMap.map(async (win: any) => {
      await airTable
        .base('appXgTB1DffKq9cHX')
        .table('DevFest')
        .create({
          first_name: body.first_name,
          last_name: body.last_name,
          email: body.email,
          phone_number: body.phone_number,
          shipping_address1: body.shipping_address1,
          shipping_address2: body.shipping_address2,
          shipping_city: body.shipping_city,
          shipping_state: body.shipping_state,
          shipping_zip: body.shipping_zip,
          shipping_country: body.shipping_country,
          shirt_size: body.shirt_size,
          company_name: win.type === 'code' ? 'Code' :  win.type === 'nocode' ? 'No Code' : 'Giveaway',
          variation: win.type,
          // @ts-ignore
          'github_handle': req?.auth?.user?.handle?.toLowerCase(),
        });

      await prisma.winners.update({
        where: {
          id: win.id,
        },
        data: {
          claimed: moment().toDate(),
        },
      });
    })
  );

  return Response.json({ invalid: false });
});

import { auth } from '@frontend/auth';
import { prisma } from '@db/prisma';

export const POST = auth(async (req, ctx) => {
  if (!req?.auth?.user) {
    return Response.json({ status: -1 });
  }
  const body = await req.json();
  if (body.id === req?.auth?.user?.id) {
    return Response.json({ status: 0 });
  }

  const findExistingBonus = await prisma.nocodeBonus.findFirst({
    where: {
      bonusFromUser: req?.auth?.user?.id!,
    },
  });

  if (findExistingBonus?.bonusToUserId === body.id) {
    return Response.json({ status: 1 });
  }

  if (findExistingBonus?.bonusToUserId) {
    return Response.json({ status: 2 });
  }

  const accessToken = await prisma.account.findFirst({
    where: {
      userId: req?.auth?.user?.id!,
    },
    select: {
      access_token: true,
    },
  });

  for (const repo of [
    'gitroomhq/postiz-app',
    'llmware-ai/llmware',
    'keephq/keep',
    'julep-ai/julep',
    'traceloop/openllmetry',
    'diggerhq/digger',
    'ComposioHQ/composio',
    'classiq/classiq-library',
    'ToolJet/ToolJet',
    'avaiga/taipy',
  ]) {
    const [owner, name] = repo.split('/');
    const load = await fetch(`https://api.github.com/user/starred/${owner}/${name}`, {
      method: 'PUT',
      headers: {
        Authorization: `token ${accessToken?.access_token}`,
        'X-GitHub-Api-Version': '2022-11-28',
        Accept: 'application/vnd.github+json',
      },
    });

    console.log(load.status);
  }

  await prisma.nocodeBonus.create({
    data: {
      bonusFromUser: req?.auth?.user?.id!,
      bonusToUserId: body.id,
    },
  });

  return Response.json({ status: 3 });
});

import { auth } from '@frontend/auth';
import { prisma } from '@db/prisma';
import { NextApiRequest, NextApiResponse } from 'next';

export default async function handler(
  req: NextApiRequest,
  res: NextApiResponse
) {
  const session = await auth(req, res);
  // @ts-ignore
  if (!session || !session.user.isMod) {
    return res.json({ error: 'Not a mod' });
  }

  const user = await prisma.user.findUnique({
    where: {
      id: req.query.id as string,
    },
    select: {
      squadId: true,
      ownedSquads: true,
      squad: {
        select: {
          members: {
            where: {
              banned: false,
              id: {
                not: req.query.id as string,
              },
            },
          },
        },
      },
    },
  });

  await prisma.user.update({
    where: {
      id: req.query.id as string,
    },
    data: {
      squadId: null,
    },
  });

  // if it was the only member of the squad, delete the squad
  if (user?.squad?.members?.length === 0) {
    await prisma.squad.delete({
      where: {
        id: user?.squadId!,
      },
    });
  }
  // if it was the owner of the squad, assign the first member as the owner
  else if (
    user?.ownedSquads?.[0]?.id &&
    (user?.squad?.members?.length || 0) > 0
  ) {
    await prisma.squad.update({
      where: {
        id: user?.squadId!,
      },
      data: {
        ownerId: user?.squad?.members?.[0]?.id!,
      },
    });
  }

  await res.revalidate(`/leaderboard/` + user?.squadId);
  return res.json({ error: 'Removed from squad' });
}

import { auth } from "@frontend/auth";
import { prisma } from "@db/prisma";

export const POST = auth(async (req, res) => {
  const body = await req.json();
  const getSquad = await prisma.user.findFirst({
    where: {
      id: req?.auth?.user?.id,
      squad: {
        is: null,
      },
    },
  });

  if (!getSquad) {
    return Response.json({
      status: 400,
      body: {
        error: "You already have a squad",
      },
    });
  }

  const { id } = await prisma.squad.create({
    data: {
      name: req?.auth?.user?.name + `'s Squad`,
      banned: false,
      allowOthersToJoin: Boolean(body.allowRandom || false),
      ownerId: req?.auth?.user?.id!,
      score: 0,
    },
  });

  await prisma.user.update({
    where: {
      id: req?.auth?.user?.id,
    },
    data: {
      squadId: id,
    },
  });

  return Response.json({
    status: 200,
    body: {
      message: "Squad created successfully",
    },
  });
});

import { auth } from '@frontend/auth';
import { prisma } from '@db/prisma';
import { starsBonus } from '@frontend/utils/stars.bonus';

const getForks = async (accessToken: string, findRepo: string) => {
  try {
    const list = await (
      await fetch(`https://api.github.com/repos/${findRepo}/forks`, {
        method: 'GET',
        headers: {
          Authorization: `token ${accessToken}`,
        },
      })
    ).json();

    return list;
  } catch (e) {
    return (
      await fetch(`https://api.github.com/repos/${findRepo}/forks`, {
        method: 'GET',
      })
    ).json();
  }
};

export const POST = auth(async (req, context) => {
  const body = await req.json();
  const findRepo = starsBonus.find((p) => body.repository === p);
  const bonuses = await prisma.bonuses.findFirst({
    where: {
      identifier: `fork-${findRepo?.toLowerCase()}`,
      userId: req?.auth?.user?.id! as string,
    },
  });

  if (bonuses) {
    return Response.json({
      status: 400,
      body: {
        error: 'You already have this bonus',
      },
    });
  }

  const account = await prisma.account.findFirst({
    where: {
      userId: req?.auth?.user?.id! as string,
    },
    select: {
      access_token: true,
    },
  });

  const list = await getForks(account?.access_token!, findRepo!);

  if (
    !list.some(
      (p: any) =>
        // @ts-ignore
        p.owner.login.toLowerCase() === req?.auth?.user.handle.toLowerCase()
    )
  ) {
    return Response.json({
      success: false,
    });
  }

  await prisma.bonuses.create({
    data: {
      identifier: `fork-${findRepo?.toLowerCase()!}`,
      score: 1,
      userId: req?.auth?.user?.id! as string,
    },
  });

  return Response.json({
    success: true,
  });
});

import { auth } from "@frontend/auth";
import { prisma } from "@db/prisma";

export const POST = auth(async (req, res) => {
  const getSquad = await prisma.user.findFirst({
    where: {
      id: req?.auth?.user?.id,
      squad: {
        is: null,
      },
    },
  });

  if (!getSquad) {
    return Response.json({
      status: 400,
      body: {
        error: "You already have a squad",
      },
    });
  }

  const findAGroup = await prisma.user.groupBy({
    by: ["squadId"],
    where: {
      banned: false,
      squad: {
        allowOthersToJoin: true,
      },
      squadId: {
        not: null,
      },
    },
    having: {
      squadId: {
        _count: {
          lt: 5,
        },
      },
    },
    orderBy: {
      _count: {
        squadId: "asc",
      },
    },
    take: 1,
  });

  if (!findAGroup.length) {
    const { id } = await prisma.squad.create({
      data: {
        name: req?.auth?.user?.name + `'s Squad`,
        banned: false,
        allowOthersToJoin: false,
        ownerId: req?.auth?.user?.id!,
        score: 0,
      },
    });

    await prisma.user.update({
      where: {
        id: req?.auth?.user?.id,
      },
      data: {
        squadId: id,
      },
    });

    return Response.json({
      status: 200,
      body: {
        message: "Squad created successfully",
      },
    });
  }

  await prisma.user.update({
    where: {
      id: req?.auth?.user?.id,
    },
    data: {
      squadId: findAGroup[0].squadId,
    },
  });

  return Response.json({
    status: 200,
    body: {
      message: "Joined Squad created successfully",
    },
  });
});

import { auth } from '@frontend/auth';
import { prisma } from '@db/prisma';
import { starsBonus } from '@frontend/utils/stars.bonus';

const getStars = async (accessToken: string) => {
  try {
    const list = await fetch(`https://api.github.com/user/starred`, {
      method: 'GET',
      headers: {
        Authorization: `token ${accessToken}`,
      },
    });

    return list.json();
  } catch (e) {
    return (
      await fetch(`https://api.github.com/user/starred`, {
        method: 'GET',
      })
    ).json();
  }
};

export const POST = auth(async (req, context) => {
  const body = await req.json();
  const findRepo = starsBonus.find((p) => body.repository === p)!;
  const bonuses = await prisma.bonuses.findFirst({
    where: {
      identifier: `star-${findRepo?.toLowerCase()}`,
      userId: req?.auth?.user?.id! as string,
    },
  });

  if (bonuses) {
    return Response.json({
      status: 400,
      body: {
        error: 'You already have this bonus',
      },
    });
  }

  const account = await prisma.account.findFirst({
    where: {
      userId: req?.auth?.user?.id! as string,
    },
    select: {
      access_token: true,
    },
  });

  const list = await getStars(account?.access_token!);

  if (!list.some((p: any) => starsBonus.includes(p.full_name.toLowerCase()))) {
    return Response.json({
      success: false,
    });
  }

  await prisma.bonuses.create({
    data: {
      identifier: `star-${findRepo?.toLowerCase()!}`,
      score: 1,
      userId: req?.auth?.user?.id! as string,
    },
  });

  return Response.json({
    success: true,
  });
});

